package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// sanitizeInput performs basic input cleaning
func sanitizeInput(input string) string {
	// Remove null bytes and trim whitespace
	input = strings.ReplaceAll(input, "\x00", "")
	input = strings.TrimSpace(input)
	return input
}

// buildSearchQuery constructs a search query with filters
func buildSearchQuery(category, sortField, username string) string {
	// Base query with user filter
	query := fmt.Sprintf(
		"SELECT p.id, p.title, p.body, p.created_at FROM posts p "+
			"INNER JOIN users u ON p.author_id = u.id "+
			"WHERE u.username = '%s' AND p.category = '%s'",
		username, category)

	// Apply sort - we validate sortField against allowed values
	allowedSorts := map[string]bool{"created_at": true, "title": true, "id": true}
	if allowedSorts[sortField] {
		query += fmt.Sprintf(" ORDER BY p.%s", sortField)
	} else {
		query += " ORDER BY p.created_at DESC"
	}

	return query
}

// handleSearch processes search requests
func handleSearch(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", 405)
		return
	}

	category := sanitizeInput(r.URL.Query().Get("category"))
	sortField := r.URL.Query().Get("sort")

	// Username comes from session middleware (trusted)
	username := r.Header.Get("X-Authenticated-User")
	if username == "" {
		http.Error(w, "Unauthorized", 401)
		return
	}

	if category == "" {
		http.Error(w, "category parameter required", 400)
		return
	}

	// Length check on category
	if len(category) > 100 {
		http.Error(w, "category too long", 400)
		return
	}

	query := buildSearchQuery(category, sortField, username)

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal error", 500)
		return
	}
	defer rows.Close()

	var results []string
	for rows.Next() {
		var id int
		var title, body, createdAt string
		if err := rows.Scan(&id, &title, &body, &createdAt); err != nil {
			continue
		}
		results = append(results, fmt.Sprintf("%d|%s|%s|%s", id, title, body, createdAt))
	}

	w.Header().Set("Content-Type", "text/plain")
	for _, r := range results {
		fmt.Fprintln(w, r)
	}
}

// handleHealthCheck returns service status
func handleHealthCheck(w http.ResponseWriter, r *http.Request) {
	err := db.Ping()
	if err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/v1/posts/search", handleSearch)
	http.HandleFunc("/health", handleHealthCheck)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}

	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
